sections.css:
.hero{position: relative; min-height: 100vh; display: flex; align-items: center; overflow: hidden; padding: 0px 4rem;}
.savanna-portal{position: absolute; right: -5%; top: 50%; transform: translateY(-50%) rotate(-2deg); width: 62vw; height: 72vh; z-index: 1; animation: 12s ease-in-out 0s infinite alternate none running lens-drift;}
.portal-mask{width: 100%; height: 100%; position: relative; border-radius: var(--r-lens); overflow: hidden; box-shadow: oklch(0.85 0.12 70 / 0.15) 0px 0px 80px inset, oklch(0.75 0.15 50 / 0.25) 0px 0px 120px, oklch(0.12 0.03 40 / 0.6) 0px 40px 100px;}
.portal-mask::before{content: ""; position: absolute; inset: -2px; z-index: 3; background: transparent; border-radius: var(--r-lens); box-shadow: oklch(0.85 0.12 70 / 0.2) 0px 0px 0px 3px inset; pointer-events: none;}
.portal-mask::after{content: ""; position: absolute; inset: 0px; z-index: 2; background: transparent; backdrop-filter: none; pointer-events: none; border-radius: var(--r-lens);}
.portal-video{width: 100%; height: 100%; object-fit: cover; filter: none; transform: none; transition: none;}
.grass-overlay{position: absolute; inset: 0px; z-index: 4; pointer-events: none; background: none; opacity: 0; border-radius: var(--r-lens);}
.hero-content{position: relative; z-index: 10; max-width: 42%; padding-top: 6rem;}
.hero-eyebrow{display: flex; align-items: center; gap: 0.75rem; font-family: var(--font-data); font-size: 0.62rem; letter-spacing: 0.3em; text-transform: uppercase; color: var(--ochre-glow); margin-bottom: 1.5rem; opacity: 0; animation: 1s ease 0.3s 1 normal forwards running fade-up;}
.eyebrow-line{width: 40px; height: 1px; background: linear-gradient(to right, var(--ochre-glow), transparent);}
.hero-title{font-family: var(--font-display); font-size: clamp(3.2rem, 5.5vw, 7rem); font-weight: 400; line-height: 0.9; color: var(--ivory-mist); letter-spacing: -0.02em; margin-bottom: 2rem; opacity: 0; animation: 1s ease 0.5s 1 normal forwards running fade-up;}
.hero-title em{font-style: italic; color: var(--ochre-glow); display: block;}
.hero-body{font-family: var(--font-ui); font-size: 0.88rem; line-height: 1.75; font-weight: 400; color: oklch(0.85 0.12 70 / 0.65); max-width: 36ch; margin-bottom: 2.5rem; opacity: 0; animation: 1s ease 0.7s 1 normal forwards running fade-up;}
.hero-ctas{display: flex; align-items: center; gap: 1.25rem; flex-wrap: wrap; opacity: 0; animation: 1s ease 0.9s 1 normal forwards running fade-up;}
.btn-primary{position: relative; overflow: hidden; padding: 0.85rem 2rem; background: oklch(0.85 0.12 70 / 0.12); border: 1px solid oklch(0.85 0.12 70 / 0.3); border-radius: 44% 56% 38% 62% / 52% 44% 56% 48%; color: var(--ivory-mist); font-family: var(--font-ui); font-size: 0.72rem; font-weight: 700; letter-spacing: 0.2em; text-transform: uppercase; cursor: none; text-decoration: none; backdrop-filter: var(--blur-glass); box-shadow: oklch(0.85 0.12 70 / 0.2) 0px 1px 0px inset, oklch(0.12 0.03 40 / 0.3) 0px -1px 0px inset, oklch(0.12 0.03 40 / 0.4) 0px 8px 32px; transition: 0.4s cubic-bezier(0.22, 1, 0.36, 1);}
.btn-primary::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(at 50% 0%, oklch(0.85 0.12 70 / 0.25) 0%, transparent 70%); opacity: 0; transition: opacity 0.3s;}
.btn-primary:hover{transform: translateY(-2px) scale(1.02);}
.btn-primary:hover::before{opacity: 1;}
.btn-ghost{display: flex; align-items: center; gap: 0.5rem; color: oklch(0.85 0.12 70 / 0.55); font-family: var(--font-data); font-size: 0.62rem; letter-spacing: 0.15em; text-transform: uppercase; cursor: none; text-decoration: none; transition: color 0.3s;}
.btn-ghost::after{content: "→"; font-size: 1rem; transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1);}
.btn-ghost:hover{color: var(--ochre-glow);}
.btn-ghost:hover::after{transform: translateX(6px);}
.telemetry-hud{position: absolute; bottom: 2rem; left: 2rem; z-index: 12; opacity: 0; animation: 1s ease 1.2s 1 normal forwards running fade-up;}
.hud-panel{background: oklch(0.12 0.03 40 / 0.65); backdrop-filter: var(--blur-glass); border: 1px solid oklch(0.85 0.12 70 / 0.12); border-radius: 28% 72% 22% 78% / 42% 32% 68% 58%; padding: 1rem 1.4rem; font-family: var(--font-data); font-size: 0.58rem; color: oklch(0.85 0.12 70 / 0.7); letter-spacing: 0.1em; box-shadow: oklch(0.85 0.12 70 / 0.1) 0px 1px 0px inset;}
.hud-row{display: flex; gap: 1.5rem; margin-bottom: 0.3rem;}
.hud-row:last-child{margin: 0px;}
.hud-label{color: oklch(0.55 0.14 50 / 0.6);}
.hud-value{color: var(--ochre-glow);}
.scroll-hint{position: absolute; bottom: 2.5rem; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 0.5rem; font-family: var(--font-data); font-size: 0.55rem; letter-spacing: 0.3em; text-transform: uppercase; color: oklch(0.85 0.12 70 / 0.3); z-index: 10; animation: 1s ease 1.5s 1 normal both running fade-up;}
.scroll-track{width: 1px; height: 48px; background: linear-gradient(to bottom, var(--ochre-glow), transparent); animation: 2.5s ease-in-out 0s infinite normal none running scroll-pulse;}
@media (max-width: 900px){.hero{padding: 0px 1.5rem;}}
@media (max-width: 900px){.hero-content{max-width: 100%; z-index: 10;}}
@media (max-width: 900px){.savanna-portal{opacity: 0.3; width: 100vw; right: 0px; height: 55vh; top: auto; bottom: 0px; transform: none; animation: auto ease 0s 1 normal none running none;}}
@media (max-width: 900px){.hero-title{font-size: 2.8rem;}}

.telemetry-section{position: relative; padding: 7rem 4rem; overflow: hidden;}
.section-label{display: flex; align-items: center; gap: 1rem; font-family: var(--font-data); font-size: 0.6rem; letter-spacing: 0.35em; text-transform: uppercase; color: var(--sienna-mid); margin-bottom: 1rem;}
.section-label-line{width: 32px; height: 1px; background: var(--sienna-mid);}
.section-title{font-family: var(--font-title); font-size: clamp(2.2rem, 4vw, 4.5rem); font-weight: 700; line-height: 1; color: var(--ivory-mist); letter-spacing: -0.02em; max-width: 14ch; margin-bottom: 4rem;}
.section-title span{color: var(--ochre-glow); font-style: italic;}
.card-river{display: flex; gap: 2rem; flex-wrap: wrap; position: relative;}
.card-river::before{content: ""; position: absolute; top: -40px; left: 10%; right: 10%; height: 80px; background: radial-gradient(oklch(0.85 0.12 70 / 0.06) 0%, transparent 70%); pointer-events: none;}
.tech-card{position: relative; flex: 1 1 280px; max-width: 360px; padding: 2.2rem 2rem; background: oklch(0.18 0.04 45 / 0.7); backdrop-filter: var(--blur-glass); border: 1px solid oklch(0.85 0.12 70 / 0.08); border-radius: var(--r-card); overflow: hidden; transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.5s; cursor: none; will-change: transform;}
.tech-card::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(at 30% 0%, oklch(0.85 0.12 70 / 0.08) 0%, transparent 60%); opacity: 0; transition: opacity 0.4s; pointer-events: none;}
.tech-card::after{content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 1px; background: linear-gradient(to right, transparent, oklch(0.85 0.12 70 / 0.3), transparent); opacity: 0.5;}
.tech-card:hover{transform: translateY(-8px) rotate(0.5deg); box-shadow: oklch(0.12 0.03 40 / 0.5) 0px 32px 80px, oklch(0.85 0.12 70 / 0.15) 0px 0px 0px 1px;}
.tech-card:hover::before{opacity: 1;}
.card-icon{width: 48px; height: 48px; margin-bottom: 1.5rem; border-radius: 35% 65% 42% 58% / 50% 38% 62% 50%; background: oklch(0.85 0.12 70 / 0.1); border: 1px solid oklch(0.85 0.12 70 / 0.15); display: flex; align-items: center; justify-content: center; font-size: 1.3rem; box-shadow: oklch(0.85 0.12 70 / 0.1) 0px 0px 16px inset;}
.card-kicker{font-family: var(--font-data); font-size: 0.56rem; letter-spacing: 0.25em; text-transform: uppercase; color: var(--sienna-mid); margin-bottom: 0.5rem;}
.card-name{font-family: var(--font-title); font-size: 1.3rem; font-weight: 700; line-height: 1.1; color: var(--ivory-mist); margin-bottom: 0.8rem;}
.card-desc{font-size: 0.8rem; line-height: 1.7; color: oklch(0.85 0.12 70 / 0.5);}
.card-metric{margin-top: 1.5rem; padding-top: 1rem; border-top: 1px solid oklch(0.85 0.12 70 / 0.08); display: flex; justify-content: space-between; align-items: baseline; font-family: var(--font-data); font-size: 0.6rem;}
.metric-val{font-size: 1.4rem; color: var(--ochre-glow); font-weight: 700;}
.metric-label{color: oklch(0.85 0.12 70 / 0.35); letter-spacing: 0.1em;}
.stalk{opacity: 0; transform: translateY(32px); transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1), transform 0.9s cubic-bezier(0.22, 1, 0.36, 1); will-change: transform, opacity;}
.stalk.in-view{opacity: 1; transform: translateY(0px);}
.stalk-delay-1{transition-delay: 0.1s;}
.stalk-delay-2{transition-delay: 0.2s;}
.stalk-delay-3{transition-delay: 0.3s;}
@media (max-width: 900px){.telemetry-section{padding: 4rem 1.5rem;}}

.section-glow{position: relative; padding: 8rem 4rem;}
.section-glow::before{content: ""; position: absolute; left: 50%; top: 0px; transform: translateX(-50%); width: 60%; height: 1px; background: radial-gradient(oklch(0.85 0.12 70 / 0.3) 0%, transparent 70%);}
.section-label{display: flex; align-items: center; gap: 1rem; font-family: var(--font-data); font-size: 0.6rem; letter-spacing: 0.35em; text-transform: uppercase; color: var(--sienna-mid); margin-bottom: 1rem;}
.section-label-line{width: 32px; height: 1px; background: var(--sienna-mid);}
.section-title{font-family: var(--font-title); font-size: clamp(2.2rem, 4vw, 4.5rem); font-weight: 700; line-height: 1; color: var(--ivory-mist); letter-spacing: -0.02em; max-width: 14ch; margin-bottom: 4rem;}
.section-title span{color: var(--ochre-glow); font-style: italic;}
.biome-section{position: relative; padding: 7rem 4rem; overflow: hidden;}
.biome-grid{display: grid; grid-template-columns: 1.2fr 1fr; gap: 4rem; align-items: center;}
.biome-visual{position: relative; height: 500px;}
.biome-orb{position: absolute; border-radius: var(--r-pill); animation: auto ease-in-out 0s infinite alternate none running orb-float;}
.biome-orb-1{width: 340px; height: 340px; top: 0px; left: 0px; background: radial-gradient(at 35% 35%, oklch(0.78 0.18 68 / 0.15), oklch(0.22 0.06 50 / 0.05)); border: 1px solid oklch(0.85 0.12 70 / 0.1); backdrop-filter: blur(40px); animation-duration: 7s; box-shadow: oklch(0.85 0.12 70 / 0.06) 0px 0px 60px inset;}
.biome-orb-2{width: 240px; height: 260px; bottom: 0px; right: 0px; background: radial-gradient(at 60% 60%, oklch(0.55 0.12 145 / 0.12), transparent); border: 1px solid oklch(0.55 0.12 145 / 0.15); animation-duration: 9s;}
.biome-orb-3{width: 160px; height: 180px; top: 50%; left: 55%; transform: translate(-50%, -50%); background: radial-gradient(oklch(0.75 0.15 50 / 0.2), transparent); animation-duration: 5s; border: 1px solid oklch(0.75 0.15 50 / 0.2); backdrop-filter: blur(20px);}
.spec-list{list-style: none; margin-top: 1.5rem;}
.spec-list li{display: flex; justify-content: space-between; align-items: center; padding: 0.65rem 0px; border-bottom: 1px solid oklch(0.85 0.12 70 / 0.06); font-size: 0.8rem; transition: background 0.2s;}
.spec-list li:last-child{border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor;}
.spec-key{color: oklch(0.85 0.12 70 / 0.45); font-family: var(--font-data); font-size: 0.62rem; letter-spacing: 0.1em;}
.spec-val{color: var(--ivory-mist); font-weight: 600;}
.spec-badge{font-family: var(--font-data); font-size: 0.52rem; letter-spacing: 0.15em; padding: 0.2rem 0.5rem; border-radius: 99px; background: oklch(0.55 0.12 145 / 0.15); border: 1px solid oklch(0.55 0.12 145 / 0.3); color: oklch(0.7 0.14 145);}
.stalk{opacity: 0; transform: translateY(32px); transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1), transform 0.9s cubic-bezier(0.22, 1, 0.36, 1); will-change: transform, opacity;}
.stalk.in-view{opacity: 1; transform: translateY(0px);}
.stalk-delay-1{transition-delay: 0.1s;}
.stalk-delay-2{transition-delay: 0.2s;}
.stalk-delay-3{transition-delay: 0.3s;}
@media (max-width: 900px){.section-glow, .biome-section{padding: 4rem 1.5rem;}}
@media (max-width: 900px){.biome-grid{grid-template-columns: 1fr;}}

