.genome-node{position: relative; padding: 1.5rem; background: oklch(0.16 0.04 45 / 0.6); border: 1px solid oklch(0.85 0.12 70 / 0.07); border-radius: var(--r-squircle); backdrop-filter: blur(20px); transition: 0.4s cubic-bezier(0.22, 1, 0.36, 1); cursor: none; overflow: hidden;}
.genome-node::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(ellipse at var(--mx, 50%) var(--my, 50%), oklch(85% 0.12 70 / 0.07) 0%, transparent 60%); pointer-events: none;}
